import math

def kl_divergence(p: list, q: list) -> float:
    """KL(p || q) = sum_i p_i * log(p_i / q_i), skipping p_i == 0."""
    total = 0.0
    for pi, qi in zip(p, q):
        if pi > 0:
            total += pi * math.log(pi / qi)
    return round(total, 4)

print(kl_divergence([0.4942, 0.2998, 0.206], [0.4192, 0.3265, 0.2543]))

import math

def temperature_softmax(logits: list, T: float) -> list:
    exps = [math.exp(x / T) for x in logits]
    s = sum(exps)
    return [round(e / s, 4) for e in exps]

def kl_divergence(p: list, q: list) -> float:
    total = 0.0
    for pi, qi in zip(p, q):
        if pi > 0:
            total += pi * math.log(pi / qi)
    return round(total, 4)

def soft_target_loss(teacher_logits: list, student_logits: list, T: float) -> float:
    """KL divergence between softened teacher and student, rescaled by T^2."""
    p = temperature_softmax(teacher_logits, T)
    q = temperature_softmax(student_logits, T)
    kl = kl_divergence(p, q)
    return round(kl * (T ** 2), 4)

print(soft_target_loss([4.0, 2.0, 0.5], [3.0, 2.0, 1.0], 4))
